id":{"$ref":"#/definitions/uuid"},"name":{"$ref":"#/definitions/styleName"},"fill":{"$ref":"#/definitions/uuid"},"border":{"$ref":"#/definitions/uuid"},"text":{"$ref":"#/definitions/uuid"}}},"styleButton":{"title":"StyleButton","$comment":"Un bouton : aplat (fill), dégradé (de fill à end), bordure (border) ou texte seul ; label est la couleur du texte. Toutes les couleurs restent, même celles que le style n'emploie pas : changer de style ne perd rien. rounded : l'arrondi de la charte. Le premier sert aux boutons de l'app.","type":"object","additionalProperties":false,"required":["id","name","kind","shape","fill","end","border","label"],"properties":{"id":{"$ref":"#/definitions/uuid"},"name":{"$ref":"#/definitions/styleName"},"kind":{"enum":["flat","gradient","outline","text"]},"shape":{"enum":["rounded","pill","square"]},"fill":{"$ref":"#/definitions/uuid"},"end":{"$ref":"#/definitions/uuid"},"border":{"$ref":"#/definitions/uuid"},"label":{"$ref":"#/definitions/uuid"}}},"styleFont":{"title":"StyleFont","$comment":"Une police : system (celle du téléphone) ou une police libre de Google Fonts, copiée dans le stockage de l'installation. On ne fait qu'ajouter des familles ; les épaisseurs de chacune sont dans l'admin.","type":"object","additionalProperties":false,"required":["id","name","family","weight"],"properties":{"id":{"$ref":"#/definitions/uuid"},"name":{"$ref":"#/definitions/styleName"},"family":{"enum":["system","DM Sans","DM Serif Display","Fraunces","Inter","Libre Baskerville","Lora","Merriweather","Nunito","Playfair Display","Poppins","Source Serif 4","Space Grotesk","Work Sans"]},"weight":{"enum":[400,500,600,700]}}},"styleFontRoles":{"title":"StyleFontRoles","$comment":"Où va chaque police : l'identifiant d'une police de la liste pour chaque usage.","type":"object","additionalProperties":false,"required":["brand","title","heading","body","quote","small","boxTitle","button","tabs"],"properties":{"brand":{"$ref":"#/definitions/uuid"},"title":{"$ref":"#/definitions/uuid"},"heading":{"$ref":"#/definitions/uuid"},"body":{"$ref":"#/definitions/uuid"},"quote":{"$ref":"#/definitions/uuid"},"small":{"$ref":"#/definitions/uuid"},"boxTitle":{"$ref":"#/definitions/uuid"},"button":{"$ref":"#/definitions/uuid"},"tabs":{"$ref":"#/definitions/uuid"}}},"styleSize":{"title":"StyleSize","$comment":"Une taille de texte en points, pour un texte de taille normale (le « grand texte » du téléphone l'agrandit), et son interligne.","type":"object","additionalProperties":false,"required":["size","lineHeight"],"properties":{"size":{"type":"integer","minimum":10,"maximum":48},"lineHeight":{"type":"number","minimum":1,"maximum":2}}},"styleSizes":{"title":"StyleSizes","type":"object","additionalProperties":false,"required":["title","heading","body","quote","small"],"properties":{"title":{"$ref":"#/definitions/styleSize"},"heading":{"$ref":"#/definitions/styleSize"},"body":{"$ref":"#/definitions/styleSize"},"quote":{"$ref":"#/definitions/styleSize"},"small":{"$ref":"#/definitions/styleSize"}}},"draft":{"title":"Draft","$comment":"Variante « draft » : le brouillon d'un contenu (article, épisode, méthode, chapitre, leçon, page).","type":"object","additionalProperties":false,"required":["v","title","blocks"],"properties":{"v":{"const":1},"title":{"type":"string","maxLength":200},"cover":{"$ref":"#/definitions/mediaRef"},"audio":{"$ref":"#/definitions/mediaRef"},"blocks":{"type":"array","items":{"$ref":"#/definitions/topBlock"}}}},"template":{"title":"TemplateDraft","$comment":"Variante « template » : le brouillon d'un modèle de blocs (pas de bloc lié).","type":"object","additionalProperties":false,"required":["v","title","blocks"],"properties":{"v":{"const":1},"title":{"type":"string","maxLength":200},"cover":{"$ref":"#/definitions/mediaRef"},"audio":{"$ref":"#/definitions/mediaRef"},"blocks":{"type":"array","items":{"$ref":"#/definitions/templateBlock"}}}},"published":{"title":"PublishedBody","$comment":"Variante « published » : le corps figé d'une version publiée (§ 2.4), ce que lit l'app. Blocs liés résolus en copies, fichier obligatoire dans chaque image, texte alternatif résolu.","type":"object","additionalProperties":false,"required":["v","title","blocks"],"properties":{"v":{"const":1},"title":{"type":"string","maxLength":200},"cover":{"$ref":"#/definitions/mediaRef"},"audio":{"$ref":"#/definitions/mediaRef"},"blocks":{"type":"array","items":{"$ref":"#/definitions/publishedTopBlock"}}}},"style":{"title":"AppStyle","$comment":"Variante « style » : la charte graphique de l'app (ADMIN § 1, section « App »), un seul document. Rangée avec les blocs parce qu'elle les habille, dans l'app comme dans l'aperçu de l'admin. Les références (une couleur ou une police de la liste) et les noms en double se vérifient à part : private.style_problems dans la base, styleProblems dans l'admin.","type":"object","additionalProperties":false,"required":["v","darkMode","colors","roles","tints","badges","buttons","fields","fonts","fontRoles","sizes","radius","imageRadius","shadow","underlineLinks"],"properties":{"v":{"const":1},"darkMode":{"enum":["auto","light","dark"]},"colors":{"type":"array","minItems":1,"maxItems":60,"items":{"$ref":"#/definitions/styleColor"}},"roles":{"$ref":"#/definitions/styleColorRoles"},"tints":{"type":"array","minItems":1,"maxItems":30,"items":{"$ref":"#/definitions/styleTint"}},"badges":{"type":"array","minItems":1,"maxItems":30,"items":{"$ref":"#/definitions/styleBadge"}},"buttons":{"type":"array","minItems":1,"maxItems":30,"items":{"$ref":"#/definitions/styleButton"}},"fields":{"enum":["outline","filled","underline"]},"fonts":{"type":"array","minItems":3,"maxItems":12,"items":{"$ref":"#/definitions/styleFont"}},"fontRoles":{"$ref":"#/definitions/styleFontRoles"},"sizes":{"$ref":"#/definitions/styleSizes"},"radius":{"type":"integer","minimum":0,"maximum":24},"imageRadius":{"type":"integer","minimum":0,"maximum":24},"shadow":{"enum":["none","light","medium","strong"]},"underlineLinks":{"type":"boolean"}}}}}$blocs$::json
  end
$fn$;

-- Empreinte SHA-256 des variantes rangées ci-dessus, calculée sur leur texte : le job « Base de
-- données » la compare à blocks/generated/schema.sha256.
create or replace function private.blocks_schema_hash()
returns text
language sql
immutable
parallel safe
set search_path = ''
as $fn$
  select encode(
    sha256(convert_to(
      'draft' || E'\n' || private.blocks_schema('draft')::text || E'\n'
      || 'template' || E'\n' || private.blocks_schema('template')::text || E'\n'
      || 'published' || E'\n' || private.blocks_schema('published')::text || E'\n'
      || 'style' || E'\n' || private.blocks_schema('style')::text || E'\n',
      'UTF8'
    )),
    'hex'
  )
$fn$;

revoke execute on function private.blocks_schema(text), private.blocks_schema_hash()
from public, anon, authenticated;
